103	// Cyrus USERNAME (author tag): the pure rules. No DB, no Nxeon imports (unit-tested in test/cyrus-username.test.ts).
104	//
105	// What it is: the name an account picks the first time it opens Cyrus (Nxeon portal or cyrus.my). It is the AUTHOR TAG
106	// shown on every public mod page, listing, creator profile, download README/LICENSE and SEO markup, instead of the
107	// personal name on the Nxeon account (which is never shown publicly any more).
108	//
109	// Policy (the documented decisions):
110	//   - 3-20 characters, [a-z0-9_-] after lowercasing; must start and end with a letter or digit; no "--"/"__" runs.
111	//   - Unique case-insensitively (usernameKey = lowercase form, plain unique index). The display case the user typed is kept.
112	//   - Reserved words, brand/staff impersonation, and a profanity list are refused (also after leetspeak folding and
113	//     with separators removed: "n_x_e_o_n", "cyr0s", "adm1n" are all refused).
114	//   - Change policy: allowed once per 30 days. The released name is held for its previous owner for 90 days (CyrusUsernameHold)
115	//     so it cannot be sniped or used to pose as the account that used it. Old public profile URLs follow the new name.
116	//   - First choice is free of the 30-day wait.
117	
118	export const USERNAME_MIN = 3;
119	export const USERNAME_MAX = 20;
120	export const USERNAME_CHANGE_DAYS = 30;
121	export const USERNAME_HOLD_DAYS = 90;
122	/** The generic public label for an account that has not chosen a tag yet (never the personal name). */
123	export const UNNAMED_AUTHOR = "Cyrus creator";
124	
125	const SHAPE = /^[a-z0-9](?:[a-z0-9_-]{1,18})[a-z0-9]$/;
126	
127	/** Words that can never be a username (exact match after folding). */
128	const RESERVED = new Set([
129	  "nxeon", "nexion", "cyrus", "cyrusmy", "cyrusai", "nxlabs", "nxm", "admin", "administrator", "root", "system", "sys",
130	  "staff", "support", "help", "mod", "mods", "moderator", "modteam", "official", "team", "security", "billing", "abuse",
131	  "postmaster", "webmaster", "hostmaster", "noreply", "noreplies", "info", "contact", "sales", "legal", "privacy", "terms",
132	  "api", "app", "www", "web", "mail", "dev", "dev-team", "null", "undefined", "anonymous", "everyone", "here", "channel",
133	  "minecraft", "mojang", "microsoft", "anthropic", "claude", "openai", "paper", "papermc", "spigot", "bukkit", "purpur",
134	  "me", "you", "user", "users", "account", "login", "logout", "register", "signup", "signin", "settings", "profile",
135	  "u", "c", "new", "edit", "delete", "create", "community", "library", "download", "install", "featured", "spotlight",
136	]);
137	
138	/** Brand / authority words that may not appear INSIDE a name (impersonation): "nxeon_support", "realcyrus", "adminbob". */
139	const IMPERSONATION = ["nxeon", "nexion", "cyrus", "official", "staff", "support", "admin", "moderator", "mojang", "microsoft", "anthropic", "paperteam", "teamnx"];
140	
141	/** A deliberately small, conservative profanity/hate blocklist matched on the folded, separator-free form. */
142	const BLOCKED = [
143	  "fuck", "shit", "cunt", "bitch", "nigg", "fagg", "retard", "whore", "slut", "rapist", "nazi", "hitler", "pedo", "paedo",
144	  "cocksuck", "dickhead", "asshole", "bastard", "jihad", "killall",
145	];
146	/** Short words that are also inside innocent ones ("grape", "crisis", "essex"): refused only as a whole part of the name (or its start). */
147	const BLOCKED_EDGE = ["rape", "porn", "sex", "kkk", "isis", "suicide"];
148	
149	/** Fold look-alikes so "cyr0s"/"adm1n"/"n3xion" cannot slip past: digits and symbols that stand in for letters. */
150	export function foldForChecks(s: string): string {
151	  const map: Record<string, string> = { "0": "o", "1": "i", "3": "e", "4": "a", "5": "s", "7": "t", "8": "b", "9": "g", "$": "s", "@": "a", "!": "i" };
152	  return s.toLowerCase().replace(/[01345789$@!]/g, (c) => map[c] ?? c).replace(/[^a-z]/g, "");
153	}
154	
155	export type UsernameVerdict =
156	  | { ok: true; display: string; key: string }
157	  | { ok: false; code: "empty" | "length" | "chars" | "edges" | "runs" | "reserved" | "impersonation" | "blocked"; message: string };
158	
159	export function validateUsername(raw: unknown): UsernameVerdict {
160	  const display = typeof raw === "string" ? raw.trim() : "";
161	  if (!display) return { ok: false, code: "empty", message: "Choose a username." };
162	  if (display.length < USERNAME_MIN || display.length > USERNAME_MAX) return { ok: false, code: "length", message: `Use ${USERNAME_MIN} to ${USERNAME_MAX} characters.` };
163	  if (!/^[A-Za-z0-9_-]+$/.test(display)) return { ok: false, code: "chars", message: "Use only letters, numbers, underscore and hyphen." };
164	  const key = display.toLowerCase();
165	  if (!SHAPE.test(key)) return { ok: false, code: "edges", message: "Start and end with a letter or number." };
166	  if (/[_-]{2}/.test(key)) return { ok: false, code: "runs", message: "Do not repeat underscores or hyphens." };
167	  const folded = foldForChecks(key);
168	  const bare = key.replace(/[_-]/g, "");
169	  if (RESERVED.has(key) || RESERVED.has(bare) || RESERVED.has(folded)) return { ok: false, code: "reserved", message: "That name is reserved." };
170	  for (const w of IMPERSONATION) {
171	    if (folded.includes(w) || key.replace(/[_-]/g, "").includes(w)) return { ok: false, code: "impersonation", message: "Names that look like Nxeon, Cyrus or staff accounts are not allowed." };
172	  }
173	  for (const w of BLOCKED) {
174	    if (folded.includes(w)) return { ok: false, code: "blocked", message: "Please choose a different name." };
175	  }
176	  for (const part of key.split(/[_-]/)) {
177	    const f = foldForChecks(part);
178	    if (BLOCKED_EDGE.some((w) => f === w || (w.length >= 4 && f.startsWith(w)))) return { ok: false, code: "blocked", message: "Please choose a different name." };
179	  }
180	  return { ok: true, display, key };
181	}
182	
183	export type ChangeDecision = { ok: true } | { ok: false; reason: "too-soon"; nextAt: string; message: string };
184	
185	/** Change policy: the first choice is free; after that, once per USERNAME_CHANGE_DAYS. */
186	export function mayChangeUsername(setAt: Date | null | undefined, now: Date = new Date()): ChangeDecision {
187	  if (!setAt) return { ok: true };
188	  const next = new Date(setAt.getTime() + USERNAME_CHANGE_DAYS * 86_400_000);
189	  if (now.getTime() >= next.getTime()) return { ok: true };
190	  return { ok: false, reason: "too-soon", nextAt: next.toISOString(), message: `You can change your username again on ${next.toISOString().slice(0, 10)}.` };
191	}
192	
193	export const holdUntil = (releasedAt: Date) => new Date(releasedAt.getTime() + USERNAME_HOLD_DAYS * 86_400_000);
