246	"use client";
247	// Cyrus first-run gate: the account must choose its public author tag before it can use Cyrus (studio, app, builds).
248	// Shown in place of the Cyrus pages on BOTH hosts (nxeon.cloud portal and cyrus.my) from app/dashboard/cyrus/layout.tsx.
249	// Also used (mode="change") by the account page. Live availability uses /api/cyrus/username (rate limited).
250	import { useEffect, useRef, useState } from "react";
251	import { useRouter } from "next/navigation";
252	
253	type Check = { state: "idle" | "checking" | "ok" | "bad"; message?: string };
254	
255	export function UsernameGate({ mode = "first", current = null, suggestion = null, nextChangeAt = null, onDone }: { mode?: "first" | "change"; current?: string | null; suggestion?: string | null; nextChangeAt?: string | null; onDone?: () => void }) {
256	  const router = useRouter();
257	  const [value, setValue] = useState(mode === "first" ? suggestion ?? "" : current ?? "");
258	  const [check, setCheck] = useState<Check>({ state: "idle" });
259	  const [saving, setSaving] = useState(false);
260	  const [err, setErr] = useState<string | null>(null);
261	  const seq = useRef(0);
262	  const locked = mode === "change" && !!nextChangeAt;
263	
264	  useEffect(() => {
265	    const v = value.trim();
266	    if (!v || (mode === "change" && v === current)) { setCheck({ state: "idle" }); return; }
267	    const mine = ++seq.current;
268	    setCheck({ state: "checking" });
269	    const t = setTimeout(async () => {
270	      try {
271	        const r = await fetch(`/api/cyrus/username?name=${encodeURIComponent(v)}`, { cache: "no-store" });
272	        const j = (await r.json()) as { ok?: boolean; message?: string; error?: string };
273	        if (mine !== seq.current) return;
274	        if (r.status === 429) setCheck({ state: "bad", message: j.error ?? "Too many checks. Wait a moment." });
275	        else setCheck(j.ok ? { state: "ok", message: "Available" } : { state: "bad", message: j.message ?? j.error ?? "Not available" });
276	      } catch {
277	        if (mine === seq.current) setCheck({ state: "bad", message: "Could not check right now." });
278	      }
279	    }, 350);
280	    return () => clearTimeout(t);
281	  }, [value, mode, current]);
282	
283	  async function save(e: React.FormEvent) {
284	    e.preventDefault();
285	    if (saving || check.state !== "ok") return;
286	    setSaving(true); setErr(null);
287	    try {
288	      const r = await fetch("/api/cyrus/username", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ username: value.trim() }) });
289	      const j = (await r.json()) as { ok?: boolean; message?: string; error?: string };
290	      if (j.ok) { onDone?.(); router.refresh(); return; }
291	      setErr(j.message ?? j.error ?? "Could not save.");
292	    } catch { setErr("Could not save. Try again."); }
293	    setSaving(false);
294	  }
295	
296	  const first = mode === "first";
297	  return (
298	    <div className={first ? "mx-auto flex min-h-[70vh] w-full max-w-[520px] items-center px-4 py-10" : "w-full"}>
299	      <form onSubmit={save} className="w-full rounded-[16px] border border-white/12 bg-white/[0.04] p-6" data-testid="username-gate" aria-labelledby="cyrus-username-h">
300	        <h1 id="cyrus-username-h" className="text-[20px] font-semibold text-white">{first ? "Choose your Cyrus username" : "Your Cyrus username"}</h1>
301	        <p className="mt-2 text-[13px] leading-relaxed text-white/70">
302	          {first
303	            ? "This is your author tag. It is shown on every mod you make public, instead of your account name. It must be unique."
304	            : "Your author tag on public mods. You can change it once every 30 days; your old name is held for you for 90 days."}
305	        </p>
306	        <label htmlFor="cyrus-username" className="mt-5 block text-[12px] font-semibold uppercase tracking-wide text-white/60">Username</label>
307	        <input
308	          id="cyrus-username" name="username" autoComplete="off" autoCapitalize="none" spellCheck={false} maxLength={20}
309	          value={value} onChange={(e) => setValue(e.target.value)} disabled={locked}
310	          aria-describedby="cyrus-username-help" aria-invalid={check.state === "bad"}
311	          className="mt-1.5 w-full rounded-[11px] border border-white/20 bg-black/30 px-3.5 py-2.5 text-[15px] text-white outline-none focus:border-white/50"
312	          placeholder="your_name"
313	        />
314	        <p id="cyrus-username-help" className="mt-2 min-h-[20px] text-[12.5px]" role="status" aria-live="polite">
315	          {locked ? <span className="text-white/70">You can change it again on {nextChangeAt!.slice(0, 10)}.</span>
316	            : check.state === "checking" ? <span className="text-white/60">Checking...</span>
317	            : check.state === "ok" ? <span className="text-emerald-300">Available</span>
318	            : check.state === "bad" ? <span className="text-red-300">{check.message}</span>
319	            : <span className="text-white/55">3 to 20 characters: letters, numbers, underscore, hyphen.</span>}
320	        </p>
321	        {err ? <p className="mt-1 text-[12.5px] text-red-300" role="alert">{err}</p> : null}
322	        <button type="submit" disabled={saving || check.state !== "ok" || locked} className="mt-4 inline-flex w-full items-center justify-center rounded-[11px] bg-white px-4 py-2.5 text-[14px] font-semibold text-black transition disabled:cursor-not-allowed disabled:opacity-40">
323	          {saving ? "Saving..." : first ? "Continue to Cyrus" : "Save username"}
324	        </button>
325	        {first ? <p className="mt-3 text-[11.5px] text-white/50">You cannot use Cyrus until you pick one. Names that imitate Nxeon, Cyrus or staff are not allowed.</p> : null}
326	      </form>
327	    </div>
328	  );
329	}
