          <a className="btn-ghost" href={cancel}>Cancel</a>
        </div>
      </AuthShell>
    );
  }
  const creating = !user;
  return (
    <AuthShell heading={creating ? "Create your Cyrus account" : "Sign in to Cyrus"} sub="Cyrus is the AI mod studio by Nxeon." bullets={BULLETS}>
