const PANEL_TABS: readonly PanelTab[] = ["code", "explain", "files", "versions", "notes"];

/** v8 parts fan: every studio off (the viewer cannot see the studios). */
const OFF: Partial<Record<string, boolean>> = Object.fromEntries(STUDIO_IDS.filter((x) => x !== "code").map((x) => [x, false]));
import { loadServerContext } from "@/lib/cyrus/bridge/server-context.server";

/** Page metadata; for gated-in users also the Cyrus app icon (owner's black tile, as a vector) as the tab icon. */
export async function cyrusMetadata(): Promise<Metadata> {
  const meta: Metadata = await modBuilderMetadata("Cyrus · AI mod studio");
  if (!(await modBuilderUser().catch(() => null))) return meta;
  return {
    ...meta,
    icons: {
      icon: [
        { url: "/cyrus/brand/icon.svg", type: "image/svg+xml" },
        { url: "/cyrus/brand/icon-192.png", sizes: "192x192", type: "image/png" },
      ],
      apple: "/cyrus/brand/apple-icon.png",
    },
  };
}

/** Server half of both Cyrus routes: gate, load every build of the user, advance in-flight ones. */
export async function CyrusPage(selectedId: string | null, opts: { retarget?: string | null; tab?: string | null; server?: string | null; file?: string | null } = {}) {
  const user = await requireModBuilderUser();
  const [rows, health, servers, studios] = await Promise.all([
    cyrusDb.modBuild.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 200 }),
    svcHealth(),
    modBuilderServers(user.id),
    // Studios (R1b): visible only to preview accounts until the owner turns on cyrus_studios_enabled
    studioViewer().then((v) => !!v).catch(() => false),
  ]);
  if (selectedId && !rows.some((r) => r.id === selectedId)) notFound();
  // r38 "Create a mod for this server" (CYRUS_SERVER_BUTTON=1): the user's own server prefills the studio
  const serverContext = process.env.CYRUS_SERVER_BUTTON === "1" && !selectedId ? await loadServerContext(user.id, opts.server).catch(() => null) : null;
  const fresh = await Promise.all(rows.map((r) => (isTerminal(r.status) ? r : syncBuild(r).catch(() => r))));
  return <><h1 className="sr-only">Cyrus studio</h1><CyrusApp initialBuilds={fresh.map(toView)} servers={servers} online={!!health?.ok} userId={user.id} selectedId={selectedId} retarget={opts.retarget && (MB_VERSIONS as readonly string[]).includes(opts.retarget) ? opts.retarget : null} studios={studios} partStudios={studios ? await studioSwitches().catch(() => OFF) : OFF} tab={opts.tab === "assets" ? (studios ? "assets" : null) : opts.tab && PANEL_TABS.includes(opts.tab as PanelTab) ? (opts.tab as PanelTab) : null} file={opts.file && /^src\/main\/[A-Za-z0-9_./-]{1,200}$/.test(opts.file) && !opts.file.includes("..") ? opts.file : null} serverContext={serverContext} /></>;
}

