/**
 * NxLabs "Install on my server" for a Cyrus mod (own mods, or a PUBLISHED version of someone
 * else's): the same install plan the studio shows (lib/cyrus/lifecycle/install-plan.ts), in
 * portal theme tokens (dark + light), portalled to <body>.
 */
export function CyrusInstallButton({ buildId, label = "Install on my server", className }: { buildId: string; label?: string; className?: string }) {
  const [open, setOpen] = useState(false);
  return (
    <>
      <button type="button" onClick={() => setOpen(true)} className={className ?? "inline-flex items-center justify-center gap-1.5 rounded-[11px] border border-white/20 bg-white/[0.07] px-3.5 py-2 text-[12.5px] font-semibold text-white transition hover:bg-white/[0.12]"}>
        <Icon name="server" size={13} tone="inherit" /> {label}
      </button>
      {open && <CyrusInstallDialog buildId={buildId} onClose={() => setOpen(false)} />}
    </>
  );
}

