// Cyrus LEARNING LOOP step 3: the MINING JOB's pure core. Clusters failed / reworked / regressed builds into CANDIDATE items for a
// human to review. It never writes to a rule file, a sheet, a prompt or a router: output is data (candidates.jsonl + a review page),
// every item has status "candidate" and carries the build ids it came from.
//
// Kinds: failure-rule (a compile / Test Flight failure pattern), sheet-fact (an API fact the sheet seems to lack),
// golden-case (a request that must keep working), routing-rule (which tier may take which change), prompt-coach-gap (the
// planner / guard / coach should have asked or warned).
import { createHash } from "node:crypto";
import type { BuildSignals, Regression } from "./types";

export const CANDIDATE_KINDS = ["failure-rule", "sheet-fact", "golden-case", "routing-rule", "prompt-coach-gap",
  // path memory (./pathmemory.ts): a cheaper default path for a prompt shape, a missing recipe / starter bank entry, a recipe pitfall
  "routing-hint", "recipe-gap", "recipe-pitfall", "bank-gap"] as const;
export type CandidateKind = (typeof CANDIDATE_KINDS)[number];

export type Candidate = {
  id: string;
  kind: CandidateKind;
  title: string;
  /** Build ids (ModBuild.id) the item was derived from. Never user text. */
  evidence: string[];
  proposedText: string;
  /** 0..1: more independent builds, a rework or a regression that confirms it, and an owner-visible loss raise it. */
  confidence: number;
  rationale: string;
  status: "candidate";
  /** Which signal produced it (so a reviewer can re-derive it). */
  signal: string;
};

/** Optional text the job may attach when asked (--include-prompts). The default run passes none and no user text is read. */
export type MiningText = { changeRequest?: string | null };
export type MiningOptions = {
  /** Build id -> text, only when the operator opted in. */
  text?: Record<string, MiningText>;
  /** A pattern is a candidate from this many independent builds (default 1: a single owner-visible loss is enough to review). */
  minEvidence?: number;
  /** Put class / command names into proposed text (staff-local review). Default off: counts only, so a candidates file carries no mod names. */
  includeNames?: boolean;
};

const CORRECTION = /\b(doesn'?t|does not|didn'?t|still|again|not working|isn'?t|broken|wrong|instead|should(?:n'?t)?|only|no longer|stopped|missing|but)\b/i;

export const candidateId = (kind: string, title: string) => createHash("sha256").update(`${kind}\n${title}`).digest("hex").slice(0, 12);
